-- القياس v5 (المرحلة ج): baseline-v5 وpost-v3، غير مفعّلتين
-- ════════════════════════════════════════════════════════════════
-- مولَّد بـ scripts/questions/build-v5.mjs من supabase/content/questions/v4.2 وscripts/questions/new-v5.mjs
-- كل أداة = نظيرتها الحية (baseline-v4 / post-v2) كما هي + لكل بُعد في كل صيغة معرفتان
-- ومواقفان جديدة (توائم A/B) + عبارة ممارسة معكوسة مشتركة (الدرجات 4→0، «لا ينطبق» −1).
-- 27 فقرة جديدة في كل أداة؛ 242 صفًا إجمالًا. لا يمس الأدوات الحية ولا الإجابات.
-- التفعيل في 20261102100100_leaders_activate_v5.sql بقرار منفصل. آمن لإعادة التشغيل.

-- 1) الأداتان (العنوان والمقدمة من النظيرة الحية؛ الزمن +4 دقائق لخمس عشرة فقرة إضافية لكل مشارك)
insert into leaders.instruments (key, title_ar, kind, active, version, intro_ar, est_minutes, pairs_with)
select 'baseline-v5', title_ar, kind, false, 5, intro_ar, est_minutes + 4, null from leaders.instruments where key = 'baseline-v4'
on conflict (key) do nothing;
insert into leaders.instruments (key, title_ar, kind, active, version, intro_ar, est_minutes, pairs_with)
select 'post-v3', title_ar, kind, false, 3, intro_ar, est_minutes + 4, 'baseline-v5' from leaders.instruments where key = 'post-v2'
on conflict (key) do nothing;

